using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioLiveViewportPerformance {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic;
 static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static StudioModelDocument doc;static object kind;static MethodInfo evaluate;static int sample,changes,lastCount;static bool capture;static long previous;static double deadline;static Dictionary<string,List<double>> times=new Dictionary<string,List<double>>();static StringBuilder report=new StringBuilder();
 static void Add(string name,double ms){if(!times.TryGetValue(name,out var list))times[name]=list=new List<double>();list.Add(ms);}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{
 StudioIntegerNativeValidation.Validate();
 StudioBevelReferenceExport.Export();var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");doc=StudioModelDocument.Import(model,"Assets/ViewportPerformanceFrame.asset");controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);view.position=new Rect(0,0,1500,950);editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);doc=editor.Document;int active=doc.nodes.FindIndex(n=>n.name=="Body"&&n.mesh);editor.SelectObject(active);var mesh=editor.ActiveMesh;var points=mesh.vertices;var topology=new StudioMeshCuts(doc.nodes[active]);
 var uses=new Dictionary<(Vector3,Vector3),List<(int a,int b,Vector3 normal)>>();
 foreach(var face in topology.Faces){var origin=points[face.Vertices[0]];var normal=Vector3.zero;for(int i=1;i+1<face.Vertices.Count;i++)normal+=Vector3.Cross(points[face.Vertices[i]]-origin,points[face.Vertices[i+1]]-origin);normal.Normalize();for(int i=0;i<face.Vertices.Count;i++){int a=face.Vertices[i],b=face.Vertices[(i+1)%face.Vertices.Count];var key=StudioMeshCuts.NormalEdgePositionKeyForBevel(points[a],points[b]);if(!uses.TryGetValue(key,out var list))uses[key]=list=new List<(int,int,Vector3)>();list.Add((a,b,normal));}}
 var sharp=uses.Where(p=>p.Value.Count==2&&Vector3.Dot(p.Value[0].normal,p.Value[1].normal)<.8f).Select(p=>p.Key).ToArray();var links=new Dictionary<Vector3,List<int>>();for(int i=0;i<sharp.Length;i++)foreach(var v in new[]{sharp[i].Item1,sharp[i].Item2}){if(!links.TryGetValue(v,out var list))links[v]=list=new List<int>();list.Add(i);}var seen=new HashSet<int>();List<int> chosen=null;
 for(int seed=0;seed<sharp.Length&&chosen==null;seed++){if(!seen.Add(seed))continue;var queue=new Queue<int>();queue.Enqueue(seed);var group=new List<int>();bool closed=true;while(queue.Count>0){int i=queue.Dequeue();group.Add(i);foreach(var v in new[]{sharp[i].Item1,sharp[i].Item2}){closed&=links[v].Count==2;foreach(int j in links[v])if(seen.Add(j))queue.Enqueue(j);}}if(closed&&group.Count==40)chosen=group;}
 if(chosen==null)throw new Exception("No frame rim found");
 var edges=(List<(int a,int b)>)typeof(StudioModelEditor).GetMethod("Edges",F).Invoke(editor,null);var keys=new HashSet<(Vector3,Vector3)>(chosen.Take(21).Select(i=>sharp[i]));
 typeof(StudioModelEditor).GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Edge);for(int i=0;i<edges.Count;i++)if(keys.Contains(StudioMeshCuts.NormalEdgePositionKeyForBevel(points[edges[i].a],points[edges[i].b])))editor.Components.Add(i);
 
 editor.Frame(view);ToolChannelPane.SetFloatDefault("Bevel Edges","Width",.3f);ToolChannelPane.SetFloatDefault("Bevel Edges","Subdivisions",0);ToolChannelPane.SetFloatDefault("Bevel Edges","Tension",1);kind=Enum.Parse(typeof(StudioModelEditor).GetNestedType("LiveTool",F),"Bevel");evaluate=typeof(StudioModelEditor).GetMethod("EvaluateLiveTool",F);StudioModelEditor.SceneProfileStage=name=>{long now=Stopwatch.GetTimestamp();if(capture&&!name.EndsWith(".start"))Add(name,(now-previous)*1000d/Stopwatch.Frequency);previous=now;};report.AppendLine("Body vertices="+points.Length+" selected="+keys.Count+" pipeline="+(UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline?.name??"Built-in"));deadline=EditorApplication.timeSinceStartup+2;EditorApplication.update+=Tick;
 }catch(Exception e){Finish(e);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{capture=sample>=10;typeof(StudioModelEditor).GetField("local",F).SetValue(editor,sample>=35);ToolChannelPane.SetFloatDefault("Bevel Edges","Width",.3f+(sample%50)*.002f);var watch=Stopwatch.StartNew();evaluate.Invoke(editor,new[]{kind});double compute=watch.Elapsed.TotalMilliseconds;
 if(sample==9||sample==34||sample==59){var selected=editor.SelectedVertices();var positions=editor.ActiveMesh.vertices;var edgesForCheck=(List<(int a,int b)>)typeof(StudioModelEditor).GetMethod("Edges",F).Invoke(editor,null);var selectedPoints=new HashSet<Vector3>(editor.Components.SelectMany(i=>new[]{positions[edgesForCheck[i].a],positions[edgesForCheck[i].b]}));var expected=new HashSet<int>(Enumerable.Range(0,positions.Length).Where(i=>selectedPoints.Contains(positions[i])));if(!selected.SetEquals(expected))throw new Exception("Live bevel weld membership differs from position reference");}
var preview=(StudioMeshToolPreview)typeof(StudioModelEditor).GetField("livePreview",F).GetValue(editor);if(preview.Targets[0].StructureChanged&&capture)changes++;if(capture&&editor.ActiveMesh.vertexCount!=lastCount)report.AppendLine("Vertex count change sample="+sample+" count="+editor.ActiveMesh.vertexCount);lastCount=editor.ActiveMesh.vertexCount;watch.Restart();view.SendEvent(new Event{type=EventType.Layout,mousePosition=new Vector2(700,400)});double layout=watch.Elapsed.TotalMilliseconds;watch.Restart();view.SendEvent(new Event{type=EventType.Repaint,mousePosition=new Vector2(700,400)});double repaint=watch.Elapsed.TotalMilliseconds;if(capture){Add("evaluate",compute);Add("layout",layout);Add("repaint",repaint);Add("combined",compute+layout+repaint);Add(sample>=35?"local.combined":"world.combined",compute+layout+repaint);}capture=false;if(++sample>=60)Finish(null);
 }catch(Exception e){Finish(e);}}
 static void Finish(Exception error){EditorApplication.update-=Tick;StudioModelEditor.SceneProfileStage=null;if(error!=null)report.AppendLine(error.ToString());if(error==null){try{var wires=(System.Collections.IDictionary)typeof(StudioModelEditor).GetField("selectionWireframes",F).GetValue(editor);var wire=wires[editor.Document.nodes[editor.Active]];var buffer=(GraphicsBuffer)wire.GetType().GetField("positionBuffer",F).GetValue(wire);var positions=(List<Vector3>)wire.GetType().GetField("vertices",F).GetValue(wire);var gpu=new Vector3[positions.Count];buffer.GetData(gpu);if(!gpu.SequenceEqual(positions))throw new Exception("GPU wire range update differs from CPU geometry");report.AppendLine("GPU wire range readback PASS");var preview=(StudioMeshToolPreview)typeof(StudioModelEditor).GetField("livePreview",F).GetValue(editor);var target=preview.Targets[0];var filter=editor.Transforms[editor.Active].GetComponent<MeshFilter>();if(filter.sharedMesh==target.Live)throw new Exception("Native viewport is not using GPU preview mesh");var update=target.VertexUpdate;for(int stream=0;stream<update.Streams.Length;stream++)using(var vertexBuffer=target.RenderMesh.GetVertexBuffer(stream)){var values=new float[update.Streams[stream].Length];vertexBuffer.GetData(values,0,update.Start*update.Strides[stream],values.Length);if(!values.SequenceEqual(update.Streams[stream]))throw new Exception("Viewport GPU attributes differ from CPU patch");}report.AppendLine("GPU mesh attribute readback PASS; World and Local handles exercised");}catch(Exception e){error=e;report.AppendLine(e.ToString());}}report.AppendLine("Measured topology changes="+changes);foreach(var pair in times){var sorted=pair.Value.OrderBy(x=>x).ToArray();report.AppendLine(pair.Key+" median="+sorted[sorted.Length/2]+" p95="+sorted[(int)Math.Ceiling(sorted.Length*.95)-1]+" max="+sorted.Last());}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../live-viewport-performance.txt")),report.ToString());if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.Exit(error==null?0:1);}
}
